  S.nm = new Float32Array(NN); S.ph = new Float32Array(NN);
  for (let i = 0; i < NN; i++) {
    // clustered placement: a few super-clusters, nodes gaussian around them
    const cl = Math.floor(fr(i * 5 + 1) * 4);
    const clx = 0.2 + fr(cl * 13 + 3) * 0.6, cly = 0.2 + fr(cl * 13 + 7) * 0.6;
    const rr = fr(i * 5 + 2), th = fr(i * 5 + 4) * 6.28318;
    S.nx[i] = Math.min(0.96, Math.max(0.04, clx + Math.cos(th) * rr * 0.28));
    S.ny[i] = Math.min(0.96, Math.max(0.04, cly + Math.sin(th) * rr * 0.28));
    S.nm[i] = 0.4 + fr(i * 5 + 6) * 0.6;               // halo mass
    S.ph[i] = fr(i * 5 + 8) * 6.28318;                 // drift phase
  }
  // filament edges: connect each node to its 2 nearest neighbours
  const E = [];
  for (let i = 0; i < NN; i++) {
    const d = [];
    for (let j = 0; j < NN; j++) if (j !== i) {
      const dx = S.nx[i] - S.nx[j], dy = S.ny[i] - S.ny[j];
      d.push([dx * dx + dy * dy, j]);
    }
    d.sort((a, b) => a[0] - b[0]);
    const kn = 2 + (fr(i * 3 + 9) < 0.4 ? 1 : 0);
    for (let e = 0; e < kn && e < d.length; e++) if (i < d[e][1] || Math.hypot(S.nx[i]-S.nx[d[e][1]], S.ny[i]-S.ny[d[e][1]]) < 0.4) E.push([i, d[e][1]]);
