const edges = S.edges;
// fast per-frame LCG (stochastic sampling -> never converges)
function rr32() { S.rng = (S.rng * 1664525 + 1013904223) >>> 0; return S.rng / 4294967296; }

// ---- clock-driven slow shear + node drift (incommensurate) ----
const tt = K.t * (0.14 + P.speed * 0.22);
const drift = P.drift * u * 0.03;
const shear = Math.sin(K.t * 0.11) * 0.05 + Math.sin(K.t * 0.047 + 1.3) * 0.03;
const rot = K.t * 0.012 + Math.sin(K.t * 0.031) * 0.04;   // slow whole-web rotation
const cs = Math.cos(rot), sn = Math.sin(rot);
const px = new Float32Array(NN), py = new Float32Array(NN);
for (let i = 0; i < NN; i++) {
  let ax = (S.nx[i] - 0.5), ay = (S.ny[i] - 0.5);
  ax += drift / u * Math.sin(tt * 0.6 + S.ph[i]);
  ay += drift / u * Math.cos(tt * 0.53 + S.ph[i] * 1.7);
  ax += ay * shear;                                        // large-scale shear flow
  const rx = ax * cs - ay * sn, ry = ax * sn + ay * cs;
  px[i] = (rx + 0.5) * BW; py[i] = (ry + 0.5) * BH;
}

// ---- fade + stochastic splat into density field ----
const fade = 0.86 - P.energy * 0.06;
for (let i = 0, n = dens.length; i < n; i++) dens[i] *= fade;
const areaScale = (BW * BH) / (440 * 260);
