for (let s = 0; s < N; s++) {
  const pick = rr32();
  let x, y, w;
  if (pick < 0.70 && nE) {
    // filament: point along a random edge, gaussian across, denser near nodes
    const ei = (rr32() * nE) | 0, a = edges[ei][0], b = edges[ei][1];
    let tp = rr32();
