    tp = tp * tp * tp < rr32() ? tp : (tp < 0.5 ? tp * 0.4 : 1 - (1 - tp) * 0.4);
    const bx = px[a] + (px[b] - px[a]) * tp, by = py[a] + (py[b] - py[a]) * tp;
